// worker-configuration.d.ts is a pure ambient global script (no import/export of its
// own), generated by `wrangler types` — there is no module to `import` from, so the
// triple-slash reference is the only way to pull in its global declarations (Env,
// D1Database, CfProperties, ExecutionContext, etc.).
// eslint-disable-next-line @typescript-eslint/triple-slash-reference
/// <reference path="../worker-configuration.d.ts" />

// Secrets are not declared in wrangler.jsonc, so they are added here.
type WorkerBindings = Env & {
  SESSION_SECRET: string;
  SCRIPTORIA_API_KEY: string;
};

declare global {
  namespace App {
    interface Error {
      requestId?: string;
    }
    interface Locals {
      administratorId: string | null;
      requestId: string;
    }
    interface Platform {
      env: WorkerBindings;
      cf?: CfProperties;
      ctx: ExecutionContext;
    }
  }
}

export {};
